mapper.select:
select 
from nad_scholarship s


        and (s.title like concat('%', #{q}, '%') or s.slug like concat('%', #{q}, '%'))

    and s.country = #{country}
    and s.funding_model = #{fundingModel}
    and s.publish_status = #{publishStatus}
    and s.status = #{status}

order by s.is_featured desc, s.update_time desc, s.id desc
